// src/components/ProjectCard.tsx
"use client";

import { motion } from "framer-motion";
import Image from "next/image";
import Link from "next/link";

export interface ProjectType {
  id: string;
  title: string;
  description: string;
  imageUrl: string;
  github: string;
  liveDemo?: string;
  technologies: string[];
}

interface ProjectCardProps {
  project: ProjectType;
  index: number;
}

export default function ProjectCard({ project, index }: ProjectCardProps) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6, delay: index * 0.2 }}
      className="card flex flex-col h-full"
    >
      <div className="relative w-full h-48 mb-4 overflow-hidden rounded-t-xl">
        <Image
          src={project.imageUrl}
          alt={project.title}
          fill
          className="object-cover hover:scale-105 transition-transform duration-500"
          sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
        />
      </div>

      <h3 className="text-2xl font-bold mb-2">{project.title}</h3>

      <p className="text-secondary mb-4 flex-grow">{project.description}</p>

      <div className="flex flex-wrap gap-2 mb-4">
        {project.technologies.map((tech, i) => (
          <span
            key={i}
            className="text-xs px-2 py-1 bg-primary/20 rounded-full"
          >
            {tech}
          </span>
        ))}
      </div>

      <div className="flex gap-3 mt-auto">
        <Link
          href={project.github}
          className="flex-1 bg-primary hover:bg-primary/80 px-4 py-2 rounded-md text-white text-center transition-all hover:-translate-y-1"
          target="_blank"
          rel="noopener noreferrer"
        >
          GitHub
        </Link>

        {project.liveDemo && (
          <Link
            href={project.liveDemo}
            className="flex-1 bg-white hover:bg-white/90 px-4 py-2 rounded-md text-black text-center transition-all hover:-translate-y-1"
            target="_blank"
            rel="noopener noreferrer"
          >
            Live Demo
          </Link>
        )}

        <Link
          href={`/projects/${project.id}`}
          className="flex-1 bg-transparent border border-white hover:bg-white/10 px-4 py-2 rounded-md text-center transition-all hover:-translate-y-1"
        >
          Details
        </Link>
      </div>
    </motion.div>
  );
}
